@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class EssentiaProbe{
    static final BlockPos BASE=new BlockPos(8,205,8),SAVED=BASE.south(12),LIVE=BASE.south(20);
    static int waiting;static boolean running;
    static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    static AlchemyMachine machine(ServerLevel l,BlockPos p,AlchemyBlock block){l.getChunkAt(p);l.setBlockAndUpdate(p,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(p,block.defaultBlockState());return (AlchemyMachine)l.getBlockEntity(p);}
    static TubeEntity tube(ServerLevel l,BlockPos p,String id,Direction facing){l.getChunkAt(p);l.setBlockAndUpdate(p,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(p,EssentiaContent.TUBES.get(id).get().defaultBlockState().setValue(TubeBlock.FACING,facing));return (TubeEntity)l.getBlockEntity(p);}
    static void load(TubeEntity t,TubeState s,ServerLevel l){var tag=t.saveWithoutMetadata(l.registryAccess());tag.put("essentia_network",TubeState.CODEC.encodeStart(NbtOps.INSTANCE,s).getOrThrow());t.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));t.setChanged();}
    record Line(AlchemyMachine source,TubeEntity first,TubeEntity last,AlchemyMachine sink){}
    static Line line(ServerLevel l,String kind,Direction facing){for(var p:BlockPos.betweenClosed(BASE.offset(0,-1,0),BASE.offset(3,1,0)))l.setBlockAndUpdate(p,Blocks.AIR.defaultBlockState());var a=machine(l,BASE,AlchemyContent.ALEMBIC.get());a.insertEssence("aer",24,false);var first=tube(l,BASE.east(),kind,facing);var last=tube(l,BASE.east(2),"tube",Direction.NORTH);var jar=machine(l,BASE.east(2).below(),AlchemyContent.JAR.get());return new Line(a,first,last,jar);}
    static int sum(Line n){return n.source.total()+n.first.total()+n.last.total()+n.sink.total();}
    static void step(Line n,int count){for(int i=0;i<count;i++){n.first.serverTick();n.last.serverTick();if(i%5==0)EssentiaNetwork.pull(n.sink.getLevel(),n.sink.getBlockPos(),n.sink,Direction.UP);}}
    static void label(ServerPlayer p,AlchemyMachine m,String a){p.setPos(m.getBlockPos().getX()+.5,m.getBlockPos().getY(),m.getBlockPos().getZ()+.5);p.setItemInHand(InteractionHand.MAIN_HAND,EssentiaContent.label(a));check(m.label(p,InteractionHand.MAIN_HAND,Direction.SOUTH)==InteractionResult.SUCCESS&&p.getMainHandItem().isEmpty(),"Label not applied/consumed");}
    @SubscribeEvent public static void start(ServerStartedEvent e){String mode=System.getProperty("thaumcraft.essentiaProbe","");if(!mode.equals("write")&&!mode.equals("read"))return;var server=e.getServer();var l=server.overworld();l.getChunkAt(BASE);l.getChunkAt(SAVED);server.tickRateManager().setFrozen(false);
        if(mode.equals("read")){
            var jar=(AlchemyMachine)l.getBlockEntity(SAVED);var filter=(TubeEntity)l.getBlockEntity(SAVED.east());var valve=(TubeEntity)l.getBlockEntity(SAVED.east(2));var buffer=(TubeEntity)l.getBlockEntity(SAVED.east(3));
            check(jar.filter().equals("aer")&&jar.total()==30&&jar.suction(Direction.UP)==64,"Labeled jar lost contents/priority");check(filter.snapshot().equals(new TubeState(1,Map.of("aer",1),17,List.of(0,0,0,0,0,0),"aer",true,false,0)),"Filter/ports/essence lost");check(!valve.snapshot().flow()&&valve.snapshot().powered(),"Valve controls lost");check(buffer.snapshot().aspects().equals(Map.of("aer",4,"ignis",3))&&buffer.snapshot().chokes().equals(List.of(0,1,2,0,0,0)),"Mixed buffer/chokes lost");
            server.tickRateManager().setFrozen(true);Thaumcraft.LOGGER.info("ESSENTIA_RESTART_OK: labeled jar, filter, isolated ports, valve and mixed buffer/chokes persisted; suction recomputed");return;
        }
        var p=new ServerPlayer(server,l,new GameProfile(UUID.fromString("cbf08a68-9c9b-4b52-a522-acb6ddc25fd9"),"EssentiaProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(net.minecraft.network.chat.Component m,boolean overlay){}};
        var n=line(l,"tube",Direction.NORTH);step(n,400);check(n.sink.total()==24&&sum(n)==24,"Normal line lost/duplicated essence");
        n=line(l,"tube_filter",Direction.NORTH);check(n.first.setFilter("ignis"),"Cannot set filter");step(n,100);check(n.source.total()==24&&sum(n)==24,"Mismatched filter leaked");n.first.setFilter("aer");step(n,400);check(n.sink.total()==24&&sum(n)==24,"Matched filter failed");
        n=line(l,"tube_valve",Direction.NORTH);n.first.toggleValve();step(n,100);check(n.source.total()==24,"Closed valve leaked");n.first.toggleValve();step(n,400);check(n.sink.total()==24&&sum(n)==24,"Open valve failed");
        n=line(l,"tube_valve",Direction.NORTH);l.setBlockAndUpdate(BASE.east().above(),Blocks.REDSTONE_BLOCK.defaultBlockState());step(n,100);check(!n.first.snapshot().flow()&&n.source.total()==24,"Redstone valve did not close");l.setBlockAndUpdate(BASE.east().above(),Blocks.AIR.defaultBlockState());step(n,400);check(n.sink.total()==24&&n.first.snapshot().flow(),"Redstone release did not reopen");
        n=line(l,"tube_restrict",Direction.NORTH);step(n,400);check(n.sink.total()==24&&sum(n)==24&&n.first.suction(Direction.WEST)==15,"Restrictor did not halve suction");
        n=line(l,"tube_oneway",Direction.WEST);step(n,100);check(n.source.total()==24,"Directional tube flowed backwards");l.setBlockAndUpdate(n.first.getBlockPos(),n.first.getBlockState().setValue(TubeBlock.FACING,Direction.EAST));step(n,400);check(n.sink.total()==24&&sum(n)==24,"Directional tube did not flow along arrow");
        n=line(l,"tube",Direction.NORTH);n.first.toggleSide(Direction.EAST);step(n,100);check(n.source.total()==24&&!n.last.connects(Direction.WEST),"Isolated ports leaked or were not mirrored");n.first.toggleSide(Direction.EAST);step(n,400);check(n.sink.total()==24&&sum(n)==24,"Reopened ports failed");
        n=line(l,"tube_buffer",Direction.NORTH);step(n,400);check(n.sink.total()==24&&sum(n)==24,"Buffer line lost essence");
        n=line(l,"tube",Direction.NORTH);label(p,n.sink,"ignis");step(n,100);check(n.source.total()==24,"Labeled jar accepted wrong aspect");p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.setShiftKeyDown(true);n.sink.interact(p,InteractionHand.MAIN_HAND);p.setShiftKeyDown(false);check(n.sink.filter().isEmpty(),"Cannot remove label");step(n,400);check(n.sink.total()==24,"Unlabeled jar no longer accepts essence");
        n=line(l,"tube_buffer",Direction.NORTH);n.source.extractEssence("aer",24,false);for(int i=0;i<5;i++){check(n.first.insert("aer",Direction.WEST,false)&&n.first.insert("ignis",Direction.WEST,false),"Mixed buffer rejected unit");}check(!n.first.insert("terra",Direction.WEST,true)&&n.first.total()==10,"Buffer capacity/simulation failed");label(p,n.sink,"aer");step(n,200);check(n.sink.total()==5&&n.first.contents(Direction.EAST).equals(Map.of("ignis",5))&&sum(n)==10,"Typed buffer extraction mixed or lost essence");
        var blank=new ItemStack(EssentiaContent.LABEL.get());var phial=AlchemyContent.filled(AlchemyContent.PHIAL.get(),"aqua",10);var labels=new LabelRecipe();var ci=CraftingInput.of(2,1,List.of(blank,phial));check(labels.matches(ci,l)&&AlchemyContent.aspect(labels.assemble(ci)).equals("aqua")&&labels.getRemainingItems(ci).get(1).is(AlchemyContent.PHIAL.get()),"Label recipe did not return phial");check(!labels.matches(CraftingInput.of(2,1,List.of(blank,new ItemStack(AlchemyContent.PHIAL.get()))),l),"Blank phial created aspect label");
        var jar=machine(l,SAVED,AlchemyContent.JAR.get());jar.insertEssence("aer",30,false);label(p,jar,"aer");var drop=net.minecraft.world.level.block.Block.getDrops(jar.getBlockState(),l,SAVED,jar).getFirst();check(drop.get(EssentiaContent.FILTER.get()).equals("aer")&&AlchemyContent.amount(drop)==30,"Labeled jar drop lost components");var upgrade=new VoidJarRecipe();ci=CraftingInput.of(1,1,List.of(drop));check(upgrade.matches(ci,l)&&upgrade.assemble(ci).get(EssentiaContent.FILTER.get()).equals("aer"),"Void upgrade lost label");var v=machine(l,SAVED.west(),AlchemyContent.VOID_JAR.get());v.placeContents(upgrade.assemble(ci));check(v.filter().equals("aer")&&v.suction(Direction.UP)==48&&v.insertEssence("aer",220,false)&&v.suction(Direction.UP)==32&&v.insertEssence("aer",1,false)&&v.total()==250,"Void jar priorities/overflow wrong");check(!v.insert("ignis",Direction.UP,true),"Void jar mixed types");
        var filter=tube(l,SAVED.east(),"tube_filter",Direction.NORTH);load(filter,new TubeState(1,Map.of("aer",1),17,List.of(0,0,0,0,0,0),"aer",true,false,0),l);var valve=tube(l,SAVED.east(2),"tube_valve",Direction.NORTH);load(valve,new TubeState(1,Map.of(),63,List.of(0,0,0,0,0,0),"",false,true,0),l);l.setBlockAndUpdate(SAVED.east(2).above(),Blocks.REDSTONE_BLOCK.defaultBlockState());var buffer=tube(l,SAVED.east(3),"tube_buffer",Direction.NORTH);load(buffer,new TubeState(1,Map.of("aer",4,"ignis",3),0,List.of(0,1,2,0,0,0),"",true,false,0),l);
        var corrupt=tube(l,SAVED.east(5),"tube",Direction.NORTH);var tag=corrupt.saveWithoutMetadata(l.registryAccess());tag.put("essentia_network",StringTag.valueOf("future"));corrupt.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));check(!corrupt.supported()&&!corrupt.insert("aer",Direction.UP,false)&&corrupt.saveWithoutMetadata(l.registryAccess()).get("essentia_network").equals(StringTag.valueOf("future")),"Future state overwritten");
        longLine(l);conflict(l,p);arcane(l,p);
        l.setChunkForced(LIVE.getX()>>4,LIVE.getZ()>>4,true);var source=machine(l,LIVE,AlchemyContent.ALEMBIC.get());source.insertEssence("aer",20,false);tube(l,LIVE.east(),"tube",Direction.NORTH);tube(l,LIVE.east(2),"tube",Direction.NORTH);machine(l,LIVE.east(2).below(),AlchemyContent.JAR.get());running=true;
        Thaumcraft.LOGGER.info("ESSENTIA_RULES_OK: variants, redstone, typed transfers, buffer, labels, recipes, conservation, conflicts, range and future saves; waiting for native tickers");
    }
    static void longLine(ServerLevel l){var b=BASE.north(12);var source=machine(l,b,AlchemyContent.ALEMBIC.get());source.insertEssence("aer",10,false);var tubes=new ArrayList<TubeEntity>();for(int x=1;x<=34;x++)tubes.add(tube(l,b.east(x),"tube",Direction.NORTH));var jar=machine(l,b.east(34).below(),AlchemyContent.JAR.get());for(int i=0;i<160;i++){for(var t:tubes)t.serverTick();if(i%5==0)EssentiaNetwork.pull(l,jar.getBlockPos(),jar,Direction.UP);}check(source.total()==10&&jar.total()==0&&tubes.getFirst().suction(Direction.WEST)==0,"Suction crossed its finite range");}
    static void conflict(ServerLevel l,ServerPlayer p){var b=BASE.south(6);var mid=tube(l,b,"tube",Direction.NORTH);var west=tube(l,b.west(),"tube",Direction.NORTH);var east=tube(l,b.east(),"tube",Direction.NORTH);label(p,machine(l,b.west().below(),AlchemyContent.JAR.get()),"aer");label(p,machine(l,b.east().below(),AlchemyContent.JAR.get()),"ignis");boolean vent=false;for(int i=0;i<30;i++){mid.serverTick();west.serverTick();east.serverTick();vent|=mid.vent()>0||west.vent()>0||east.vent()>0;}check(vent,"Conflicting equally strong aspects did not vent");}
    static void arcane(ServerLevel l,ServerPlayer p){var b=BASE.west(5);l.setBlockAndUpdate(b,ArcaneContent.WORKBENCH.get().defaultBlockState());var work=(ArcaneWorkbenchEntity)l.getBlockEntity(b);p.setPos(b.getX()+.5,b.getY(),b.getZ()+.5);ResearchService.grant(p,"TUBES");work.inventory.setItem(0,new ItemStack(EssentiaContent.TUBES.get("tube").get()));work.inventory.setItem(1,new ItemStack(Blocks.LEVER));AuraData.get(l).put(AuraCell.key(b.getX()>>4,b.getZ()>>4),new AuraCell(500,500,0));check(work.craft(p)&&work.inventory.getItem(15).is(EssentiaContent.TUBES.get("tube_valve").get().asItem())&&AuraManager.get(l,b).vis()==490,"Arcane valve recipe failed native cost/output");work.inventory.setItem(15,ItemStack.EMPTY);work.inventory.setItem(0,new ItemStack(EssentiaContent.TUBES.get("tube").get()));work.inventory.setItem(12,thaumcraft.crystals.CrystalContent.essence("terra",1));check(work.craft(p)&&work.inventory.getItem(15).is(EssentiaContent.TUBES.get("tube_restrict").get().asItem())&&work.inventory.getItem(12).isEmpty(),"Shared-grid restrictor did not select earth crystals");work.inventory.setItem(15,ItemStack.EMPTY);work.inventory.setItem(0,new ItemStack(EssentiaContent.TUBES.get("tube").get()));work.inventory.setItem(11,thaumcraft.crystals.CrystalContent.essence("aqua",1));check(work.craft(p)&&work.inventory.getItem(15).is(EssentiaContent.TUBES.get("tube_oneway").get().asItem())&&work.inventory.getItem(11).isEmpty(),"Shared-grid directional recipe did not select water crystals");var items=new ArrayList<ItemStack>();for(int i=0;i<9;i++)items.add(switch(i){case 0,2,6,8->new ItemStack(AlchemyContent.PHIAL.get());case 1->new ItemStack(EssentiaContent.TUBES.get("tube_valve").get());case 3,5->new ItemStack(EssentiaContent.TUBES.get("tube").get());case 4->new ItemStack(SimpleContent.ITEMS.get("plate_iron").get());default->new ItemStack(EssentiaContent.TUBES.get("tube_restrict").get());});var recipe=new EmptyPhialRecipe();check(recipe.matches(CraftingInput.of(3,3,items),l),"Buffer pattern failed");items.set(0,AlchemyContent.filled(AlchemyContent.PHIAL.get(),"aer",10));check(!recipe.matches(CraftingInput.of(3,3,items),l),"Buffer destroyed filled phial");}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!running||++waiting<160)return;var l=e.server().overworld();var jar=(AlchemyMachine)l.getBlockEntity(LIVE.east(2).below());var source=(AlchemyMachine)l.getBlockEntity(LIVE);var a=(TubeEntity)l.getBlockEntity(LIVE.east());var b=(TubeEntity)l.getBlockEntity(LIVE.east(2));check(jar.total()==20&&source.total()+a.total()+b.total()==0,"Native ticker line failed conservation: jar="+jar.total()+", source="+source.total()+", tubes="+(a.total()+b.total()));running=false;e.server().tickRateManager().setFrozen(true);Thaumcraft.LOGGER.info("ESSENTIA_RUNTIME_OK: native tickers transferred all 20 units exactly; all deterministic rules passed");}
}
